import pytest

from app import audit as audit_mod
from app.errors import ValidationError
from app.features.refunds import refund_amount


@pytest.fixture(autouse=True)
def _clear_audit():
    audit_mod.EVENTS.clear()
    yield
    audit_mod.EVENTS.clear()


def test_no_fee():
    assert refund_amount("12.50", 0) == 1250


def test_full_fee_refunds_nothing():
    assert refund_amount("12.50", 10000) == 0


def test_fee_rounds_down():
    # 1000 cents * 333 bps // 10000 = 33 (33.3 floored)
    assert refund_amount("10", 333) == 967


def test_accepts_dollar_sign_and_no_decimals():
    assert refund_amount("$12.5", 1000) == 1125
    assert refund_amount("12", 1000) == 1080


@pytest.mark.parametrize("bps", [-1, 10001, 10**6])
def test_fee_out_of_range(bps):
    with pytest.raises(ValidationError):
        refund_amount("12.50", bps)


@pytest.mark.parametrize("bps", [1.5, "100", None, True])
def test_fee_not_int(bps):
    with pytest.raises(ValidationError):
        refund_amount("12.50", bps)


@pytest.mark.parametrize("price", ["", "abc", "1.234", "-5", "12.5.0", None])
def test_invalid_price(price):
    with pytest.raises(ValidationError):
        refund_amount(price, 100)


def test_records_audit_event_on_success():
    refund_amount("12.50", 0)
    assert audit_mod.EVENTS == [
        {"event": "refund_calculated", "price_cents": 1250, "fee_bps": 0, "refund_cents": 1250}
    ]


def test_no_audit_event_on_failure():
    with pytest.raises(ValidationError):
        refund_amount("12.50", 10001)
    assert audit_mod.EVENTS == []

